import { _decorator, Component, director, easing, game, Node, tween, Tween, v2, v3 } from 'cc';
import { FullView, onMount, onShow, PopView } from '../../scripts/Tea/UI/UIView';
import { Path } from '../../scripts/Tea/decorators/tea.decorators';
const { ccclass, property } = _decorator;

@ccclass('HelpView')
export class HelpView extends PopView {
    @Path('popBase')
    popBase: Node = null;
    @Path('popBase/closeBtn')
    closeBtn: Node = null;
    @onMount
    mount() {
        this.closeBtn.on(Node.EventType.TOUCH_END, this.onClickCloseBtn.bind(this));
    }

    @onShow
    showPopAnim() {
        Tween.stopAllByTarget(this.popBase);
        tween(this.popBase)
            .set({ scale: v3(0, 0, 0) })
            .to(0.4, { scale: v3(1, 1, 1) }, { easing: easing.backOut })
            .start();
    }

    hidePopAnim() {
        Tween.stopAllByTarget(this.popBase);
        tween(this.popBase)
            .set({ scale: v3(1, 1, 1) })
            .to(0.4, { scale: v3(0, 0, 0) }, { easing: easing.backIn })
            .delay(0.2)
            .call(() => {
                this.hide();
            })
            .start();
    }

    onClickCloseBtn() {
        this.hidePopAnim();
    }
}